/**
 * Pins taba-rolldown to a Rolldown release.
 *
 * Separate script to avoid polluting xtask with heavy dependencies for an occasional dev task.
 * Run it through `cargo xtask rolldown`.
 *
 * All the Rolldown crates need to be pinned together, including transitive ones.
 */

import { readFileSync, writeFileSync } from "node:fs";

/** Marks where to truncate autogenerated files. */
const MARKER = "AUTOGENERATED - DO NOT EDIT BELOW HERE: See `cargo xtask rolldown pin`.\n";

/** Taba needs some Oxc crates re-exported in `taba-rolldown`, at Rolldown's required version. */
const OXC = new Set(["oxc", "oxc_resolver"]);

type Release = {
  vers: string;
  deps: { name: string; req: string; kind: "normal" | "build" | "dev"; optional: boolean }[];
  yanked: boolean;
  rust_version?: string;
};

function bail(message: string): never {
  console.error(message);
  process.exit(1);
}

/** https://doc.rust-lang.org/cargo/reference/registry-index.html#index-files */
function indexPath(crate: string) {
  if (crate.length <= 2) return `${crate.length}/${crate}`;
  if (crate.length === 3) return `3/${crate.slice(0, 1)}/${crate}`;
  return `${crate.slice(0, 2)}/${crate.slice(2, 4)}/${crate}`;
}

/** Every release of a crate from the sparse index, by version. */
async function fetchReleases(crate: string) {
  const url = `https://index.crates.io/${indexPath(crate)}`;
  const response = await fetch(url, {
    headers: { "user-agent": "taba-xtask (https://github.com/taba-build/taba)" },
  });
  if (!response.ok) bail(`${url} answered ${response.status}`);
  const lines = (await response.text()).trim().split("\n");
  const releases = lines.map((line): Release => JSON.parse(line));
  return new Map(releases.map((release) => [release.vers, release]));
}

/** Replace everything below the marker with `lines`. */
function regenerate(file: string, lines: string[]) {
  const path = new URL(`../crates/taba-rolldown/${file}`, import.meta.url);
  const [head, old] = readFileSync(path, "utf8").split(MARKER, 2);
  if (old === undefined) bail(`${path.pathname} has no marker: ${MARKER.trim()}`);
  writeFileSync(path, `${head}${MARKER}${lines.join("\n")}\n`);
}

/** Pin Rolldown's crates to `version`, and Oxc's to what Rolldown requires. */
async function pin(version: string) {
  /** Rolldown family must require their exact versions. */
  const family = new Set(["rolldown"]);
  const oxc = new Map<string, string>();
  for (const crate of family) {
    const release =
      (await fetchReleases(crate)).get(version) ?? bail(`${crate} ${version} isn't on crates.io`);
    for (const { name, req, kind, optional } of release.deps) {
      if (kind === "dev" || optional) continue;
      if (req === `^${version}`) family.add(name);
      if (OXC.has(name)) oxc.set(name, req);
    }
  }

  const oxcPins = [...oxc].sort(([a], [b]) => (a < b ? -1 : 1));
  const familyPins = [...family].sort().map((name) => [name, `=${version}`] as const);
  const pins = [...oxcPins, ...familyPins];
  const dependencies = pins.map(([name, req]) => `${name} = "${req}"`);
  const reexports = pins.map(([name]) => `pub use ${name};`);
  regenerate("Cargo.toml", dependencies);
  regenerate("src/lib.rs", reexports);
  const pinned = oxcPins.map(([name, req]) => `${name} ${req}`).join("\n");
  console.log(`rolldown =${version}\n${pinned}`);
}

/** Print each Rolldown release with its Oxc's MSRV: Rolldown declares none. */
async function msrv() {
  const oxc = await fetchReleases("oxc");
  for (const [version, release] of await fetchReleases("rolldown")) {
    const exact = release.deps
      .find(({ name, kind }) => name === "oxc" && kind !== "dev")
      ?.req.replace(/^\^/, "");
    if (exact === undefined || release.yanked) continue;
    const rustVersion = oxc.get(exact)?.rust_version ?? "none";
    console.log(`rolldown ${version.padEnd(10)} oxc ${exact.padEnd(10)} msrv(oxc) ${rustVersion}`);
  }
}

const args = process.argv.slice(2);
const [command, version] = args;
if (command === "pin" && version !== undefined && args.length === 2) {
  await pin(version);
} else if (command === "msrv" && args.length === 1) {
  await msrv();
} else {
  bail(`unknown args ${args.join(" ")}\n\nsee \`cargo xtask rolldown --help\``);
}
